import telnetlib
from re import search, finditer
from robot.api import logger


class GetCPUAddressForTTITraces(object):
    def __init__(self, host='192.168.255.1', port=15007):
        self.host = host
        self.port = port

    def get_cpu_address(self, cell, direction, is_nb_iot=0):
        """
        :param cell: define cell number (lncell id) you are interested in getting deployment
        :param direction: define direction you need - downlink, uplink or both. Input one as a string.
        :param is_nb_iot: flag for NB-IoT. In NB-IoT TTI Traces are gathered from MACDLTTI sicad
        :return: returns board, DSP and core number of MAC PS. Needed as input for ttistream
        Sample usage: get_core_number_for_tti_traces(1, "uplink") gets DSP core for UL Scheduler of cell 1
        """
        formatted_deployment = self._get_formatted_deployment()
        is_fsmr4 = True

        mac_ul_tii_index = formatted_deployment[0].index('MACULTTI')
        mac_dl_tti_index = formatted_deployment[0].index('MACDLTTI')
        lncell_index = formatted_deployment[0].index('lnCel')

        cell_index = next(
            (index for index, line in enumerate(formatted_deployment) if line[lncell_index] == str(cell)), None
        )
        if not cell_index:
            raise RuntimeError('Couldn\'t find cell {} in cell mapping: \n {}'.format(cell, formatted_deployment))

        if direction == 'uplink':
            return (
                formatted_deployment[cell_index][mac_ul_tii_index][:6]
                if not is_fsmr4
                else formatted_deployment[cell_index][mac_ul_tii_index]
            )
        elif direction == 'downlink':
            return (
                formatted_deployment[cell_index][mac_dl_tti_index][:6]
                if not is_fsmr4
                else formatted_deployment[cell_index][mac_dl_tti_index]
            )
        elif direction == 'both' and is_nb_iot == 1:
            return (
                [
                    formatted_deployment[cell_index][mac_dl_tti_index][:6],
                    formatted_deployment[cell_index][mac_dl_tti_index][:6],
                ]
                if not is_fsmr4
                else [
                    formatted_deployment[cell_index][mac_dl_tti_index],
                    formatted_deployment[cell_index][mac_dl_tti_index],
                ]
            )
        elif direction == 'both':
            return (
                [
                    formatted_deployment[cell_index][mac_dl_tti_index][:6],
                    formatted_deployment[cell_index][mac_ul_tii_index][:6],
                ]
                if not is_fsmr4
                else [
                    formatted_deployment[cell_index][mac_dl_tti_index],
                    formatted_deployment[cell_index][mac_ul_tii_index],
                ]
            )
        else:
            logger.console('Cell out of range or direction not specified...')

    def _get_formatted_deployment(self):
        """Returns formatted deployment (list of lists)"""

        temp_string = self._get_raw_deployment()
        formatted_deployment = []

        temp_string = temp_string.split('\n')[1:-1]

        lines = [line.split() for line in temp_string]

        for line in lines:
            formatted_deployment.append(line)

        return formatted_deployment

    def _get_raw_deployment(self):
        """Return unformated ouput of getCellMapping command in eNB telnet."""
        node_id = self._get_node_id()

        raw_deployment = self._aashell_cmd_execute('getCellMapping @RROMexe #{0}'.format(node_id))
        if raw_deployment is None or ('0x' not in raw_deployment and raw_deployment != ''):
            raise Exception('ERROR: Cannot fetch DSP deployment... \n')
        elif raw_deployment:
            return raw_deployment
        else:
            raise Exception('ERROR: Most probably telnet connection already open... \n')

    def _get_node_id(self):
        """
        Return address of the node where RROMexe is running
        :return address of the node where RROMexe is running
        :raise ERROR: Cannot find process RROMexe in known nodes
        :raise ERROR: Cannot fetch address of the node where RROMexe is running
        """
        nodes = []
        node_id = None

        output = self._aashell_cmd_execute('nodes -p RROMexe')
        if not output:
            raise Exception('ERROR: Cannot fetch address of the node where RROMexe is running')
        nodes_index = [i.start() for i in finditer('node', output)]

        for (i, val) in enumerate(nodes_index[:-1]):
            node = output[nodes_index[i]:nodes_index[i + 1]]
            nodes.append(node)
        nodes.append(output[nodes_index[-1]:])

        for node in nodes:
            if search('RROMexe', node) is not None:
                node_id = search(r'0x.*,', node).group().split(',')[0]
                return node_id

        if node_id is None:
            raise Exception("ERROR: Cannot find process RROMexe in known nodes")

    def _aashell_cmd_execute(self, cmd):
        """
        Starts telnet connection to AaShell and executes given cmd
        :param cmd: command which will be executed in AaShell
        :return output from AaShell console
        :raise Exception: ERROR: most probably AaShell is already open
        raise Exception: ERROR: "given_in_function_parameters_command" is not a valid AaShell command
        """
        try:
            tn = telnetlib.Telnet(self.host, self.port, 5)
        except IOError:
            logger.console('socket timeout')
            raise
        else:
            output = tn.read_until('AaShell>', 5)
            if not output:
                raise Exception("ERROR: most probably AaShell is already open")
            tn.write(cmd)
            tn.write('\n')
            output = tn.read_until('AaShell>', 5)
            if "is not a valid command" in output:
                raise Exception("ERROR: \"{0}\" is not a valid AaShell command".format(cmd))
            tn.write('quit \n')
            tn.close()
            return output
